<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetVersionVO;

trait SnippetVersionAccessor
{
    private ?SnippetVersionVO $_version = null;
    public function getVersion(): ?int
    {
        return $this->_version?->value();
    }
    public function version(): ?SnippetVersionVO
    {
        return $this->_version;
    }
    public function isVersionChanged(?self $original = null): bool
    {
        return null !== $this->_version && !$this->_version->equals($original?->_version);
    }
    public function withVersion(SnippetVersionVO|int|null $version): self
    {
        $copy = clone $this;
        $copy->_version = SnippetVersionVO::from($version);
        return $copy;
    }
}
